using System.Numerics;
namespace UltimateArena.Core;
public sealed class World {
    public const float Tick=1/60f;
    public List<Fighter> Fighters=[];public List<Projectile> Projectiles=[];public List<GameEvent> Events=[];public List<Pickup> Pickups=[];
    public float Time,RoundTime=480,Restart;public string Winner="";public int FragLimit=20;private uint random,eventId;private int projectileId,nextId;
    public World(int seed=1701,int bots=5){random=(uint)seed;foreach(int x in new[]{-18,18}){Pickups.Add(new(){Id=Pickups.Count,Kind=0,Position=new(x,0,0)});Pickups.Add(new(){Id=Pickups.Count,Kind=1,Position=new(x,3,x<0?-18:18)});}for(int i=0;i<6;i++)Pickups.Add(new(){Id=Pickups.Count,Kind=2,Weapon=i,Position=new(MathF.Cos(i*MathF.Tau/6)*11,0,MathF.Sin(i*MathF.Tau/6)*11)});string[] names=["SABLE","VECTOR","HEX","CINDER","WRAITH","NOVA","FLINT","ONYX","MOTH","ECHO"];for(int i=0;i<bots;i++)Add(names[i%names.Length],true);}
    public float Random(){random=unchecked(random*1664525+1013904223);return random/4294967296f;}
    public Fighter Add(string name,bool bot=false){var p=new Fighter{Id=++nextId,Name=name,Bot=bot,Weapon=bot?1:0};Fighters.Add(p);Spawn(p);return p;}
    public void Remove(int id){Fighters.RemoveAll(p=>p.Id==id);Projectiles.RemoveAll(p=>p.Owner==id);}
    public void Spawn(Fighter p){float Clearance(Vector3 s)=>Fighters.Where(q=>q!=p&&q.Health>0).Select(q=>Vector3.Distance(s,q.Position)).DefaultIfEmpty(999).Min();var points=Arena.Spawns.OrderByDescending(Clearance).ToArray();p.Position=points[(int)(Random()*3)%3];p.Health=100;p.Armor=35;p.Velocity=Vector3.Zero;p.Cooldown=.3f;p.Respawn=0;p.Invulnerable=1;p.Grounded=true;p.Path=[];p.Ammo=Weapons.All.Select(w=>w.Ammo).ToArray();p.Yaw=MathF.Atan2(-p.Position.X,p.Position.Z);p.Pitch=0;}
    public void Emit(EventKind kind,int owner=0,int target=0,int weapon=0,Vector3 a=default,Vector3 b=default,float value=0){Events.Add(new(++eventId,kind,owner,target,weapon,a,b,value));if(Events.Count>160)Events.RemoveAt(0);}
    public void Damage(Fighter target,float amount,Fighter owner,Vector3 knock=default){if(target.Health<=0||target.Invulnerable>0)return;target.Velocity+=knock;float absorbed=MathF.Min(target.Armor,amount*.6f);target.Armor-=absorbed;target.Health=MathF.Max(0,target.Health-(amount-absorbed));Emit(EventKind.Hit,owner.Id,target.Id,owner.Weapon,value:amount);if(target.Health<=0){target.Deaths++;target.Respawn=2;owner.Score+=target==owner?-1:1;Emit(EventKind.Kill,owner.Id,target.Id,owner.Weapon);if(owner.Score>=FragLimit)Finish(owner);}}
    private void Finish(Fighter p){if(Winner.Length>0)return;Winner=p.Name;Restart=8;Emit(EventKind.Round,p.Id);}
    public void Fire(Fighter p,bool alt=false){var w=Weapons.All[p.Weapon];if(p.Cooldown>0||p.Health<=0||Winner.Length>0)return;int cost=alt&&p.Weapon==2?2:1;if(p.Ammo[p.Weapon]<cost){p.Cooldown=.2f;return;}p.Ammo[p.Weapon]-=cost;p.Cooldown=w.Delay*(alt&&p.Weapon==1?.55f:1);var origin=p.Position+new Vector3(0,1.42f,0);float spread=w.Spread,damage=w.Damage;int pellets=w.Pellets;if(alt&&p.Weapon==0){spread*=.25f;damage*=1.25f;p.Cooldown=.4f;}if(alt&&p.Weapon==1){spread=.23f;damage=12;}if(alt&&p.Weapon==2){spread=.14f;pellets=16;p.Cooldown=1.1f;}if(p.Input.Crouch)spread*=.5f;
        if(w.Kind is ShotKind.Rocket or ShotKind.Grenade){if(Projectiles.Count>=64)return;var dir=MathEx.Direction(p.Yaw,p.Pitch);Projectiles.Add(new(){Id=++projectileId,Owner=p.Id,Weapon=p.Weapon,Position=origin+dir*.55f,Velocity=dir*(w.Kind==ShotKind.Rocket?23:17)+new Vector3(0,w.Kind==ShotKind.Grenade?3:0,0),Life=w.Kind==ShotKind.Rocket?5:2.5f,Damage=damage,Sticky=alt&&w.Kind==ShotKind.Grenade,Homing=alt&&w.Kind==ShotKind.Rocket});Emit(EventKind.Shot,p.Id,weapon:p.Weapon,a:origin);return;}
        for(int i=0;i<pellets;i++){float ya=p.Yaw+(Random()-Random())*spread*.5f,pi=p.Pitch+(Random()-Random())*spread*.5f;var dir=MathEx.Direction(ya,pi);float distance=Arena.Trace(origin,dir);Fighter? hit=null;foreach(var target in Fighters)if(target!=p&&target.Health>0){var t=Arena.RayBox(origin,dir,new(target.Position+new Vector3(0,.85f,0),new(.8f,1.7f,.8f)),distance);if(t.HasValue){distance=t.Value;hit=target;}}if(hit!=null){bool head=origin.Y+dir.Y*distance>hit.Position.Y+1.32f;Damage(hit,damage*(head?1.4f:1),p);}Emit(EventKind.Trace,p.Id,weapon:p.Weapon,a:origin,b:origin+dir*distance);}
        Emit(EventKind.Shot,p.Id,weapon:p.Weapon,a:origin);
    }
    private void Explode(Projectile q){var owner=Fighters.Find(p=>p.Id==q.Owner);if(owner==null)return;Emit(EventKind.Explosion,q.Owner,weapon:q.Weapon,a:q.Position,value:5);foreach(var p in Fighters){var delta=p.Position+new Vector3(0,.8f,0)-q.Position;float d=delta.Length();if(d<5.3f&&Arena.Trace(q.Position+new Vector3(0,.05f,0),MathEx.SafeNormal(delta),d)>=d-.15f)Damage(p,q.Damage*(1-d/5.3f)*(p==owner?.65f:1),owner,MathEx.SafeNormal(delta)*9+new Vector3(0,5,0));}}
    private void Bot(Fighter p,float dt){var target=Fighters.Where(q=>q!=p&&q.Health>0).MinBy(q=>Vector3.DistanceSquared(q.Position,p.Position));if(target==null){p.Input=default;return;}var delta=target.Position-p.Position;float dist=MathEx.Horizontal(delta);bool visible=Arena.Visible(p.Position,target.Position);p.Think-=dt;p.Repath-=dt;if(p.Think<=0){p.Think=.2f+Random()*.16f;int want=dist<6?2:dist>19?3:Random()<.15f?4:1;if(p.Ammo[want]>0)p.Weapon=want;else if(p.Ammo[p.Weapon]<=0)p.Weapon=Array.FindIndex(p.Ammo,a=>a>0);if(p.Weapon<0)p.Weapon=0;}
        var input=new InputState{Weapon=p.Weapon};if(visible&&dist<25){float desired=MathF.Atan2(delta.X,-delta.Z),error=MathEx.Angle(desired-p.Yaw);p.Yaw+=Math.Clamp(error,-dt*3.8f,dt*3.8f);float aim=MathF.Atan2(delta.Y-.15f,dist)+MathF.Sin(Time*3+p.Id)*.035f;p.Pitch+=Math.Clamp(aim-p.Pitch,-dt*2,dt*2);input.Side=MathF.Sin(Time*.8f+p.Id)>0?.8f:-.8f;input.Forward=dist>13?.65f:dist<5?-.6f:0;input.Fire=MathF.Abs(error)<.13f&&p.Invulnerable==0;input.Alt=p.Weapon==4&&dist>15;}else{if(p.Repath<=0||p.Path.Count==0){p.Path=Navigation.Find(p.Position,target.Position);p.Repath=.8f;}while(p.Path.Count>0&&MathEx.Horizontal(p.Position-p.Path[0])<.6f)p.Path.RemoveAt(0);if(p.Path.Count>0){var d=p.Path[0]-p.Position;p.Yaw=MathF.Atan2(d.X,-d.Z);p.Pitch=0;input.Forward=1;}}input.Yaw=p.Yaw;input.Pitch=p.Pitch;p.Input=input;
    }
    public void Step(float dt=Tick){Time+=dt;if(Winner.Length>0){Restart-=dt;if(Restart<=0){Winner="";RoundTime=480;foreach(var p in Fighters){p.Score=0;p.Deaths=0;Spawn(p);}}return;}RoundTime-=dt;if(RoundTime<=0&&Fighters.Count>0)Finish(Fighters.MaxBy(p=>p.Score)!);
        foreach(var p in Fighters){if(p.Health<=0){p.Respawn-=dt;if(p.Respawn<=0)Spawn(p);continue;}p.Cooldown=MathF.Max(0,p.Cooldown-dt);p.Invulnerable=MathF.Max(0,p.Invulnerable-dt);if(p.Bot)Bot(p,dt);p.Yaw=p.Input.Yaw;p.Pitch=Math.Clamp(p.Input.Pitch,-1.45f,1.45f);p.Weapon=Math.Clamp(p.Input.Weapon,0,5);Movement.Step(p,p.Input,dt);if(p.Input.Fire||(p.Input.Alt&&p.Weapon!=3))Fire(p,p.Input.Alt);}
        foreach(var q in Projectiles){q.Life-=dt;q.Age+=dt;var owner=Fighters.Find(p=>p.Id==q.Owner);if(owner==null){q.Life=-1;continue;}if(q.Homing){var t=Fighters.Where(p=>p!=owner&&p.Health>0&&Arena.Visible(q.Position,p.Position)).MinBy(p=>Vector3.DistanceSquared(p.Position,q.Position));if(t!=null)q.Velocity=Vector3.Lerp(q.Velocity,MathEx.SafeNormal(t.Position+new Vector3(0,.8f,0)-q.Position)*20,dt*2.2f);}
            if(!q.Stuck){if(q.Weapon==5)q.Velocity.Y-=15*dt;float length=q.Velocity.Length(),reach=length*dt;float hit=Arena.Trace(q.Position,MathEx.SafeNormal(q.Velocity),reach+.12f);if(hit<reach+.12f){if(q.Weapon==5){if(q.Sticky){q.Stuck=true;q.Life=12;}else{q.Velocity.Y=MathF.Abs(q.Velocity.Y)*.6f;q.Velocity.X*=-.65f;q.Velocity.Z*=-.65f;}}else q.Life=0;}else q.Position+=q.Velocity*dt;}
            foreach(var p in Fighters)if(p.Health>0&&(p!=owner||q.Age>.5f)&&Vector3.Distance(p.Position+new Vector3(0,.8f,0),q.Position)<(q.Stuck?2.2f:.8f))q.Life=0;if(q.Life<=0)Explode(q);
        }Projectiles.RemoveAll(q=>q.Life<=0);
        foreach(var pick in Pickups){if(pick.Ready>Time)continue;foreach(var p in Fighters)if(p.Health>0&&Vector3.Distance(p.Position,pick.Position)<1.2f){bool used=false;if(pick.Kind==0&&p.Health<100){p.Health=MathF.Min(100,p.Health+35);used=true;}if(pick.Kind==1&&p.Armor<100){p.Armor=MathF.Min(100,p.Armor+50);used=true;}if(pick.Kind==2&&p.Ammo[pick.Weapon]<Weapons.All[pick.Weapon].Ammo){p.Ammo[pick.Weapon]=Math.Min(Weapons.All[pick.Weapon].Ammo,p.Ammo[pick.Weapon]+(int)MathF.Ceiling(Weapons.All[pick.Weapon].Ammo*.3f));used=true;}if(used){pick.Ready=Time+12;Emit(EventKind.Pickup,p.Id,value:pick.Kind);break;}}}
    }
}
